void mostrarNumeros(int v[], int n) {
  int i;

  for (i = 0; i < n; i++) {
    printf("%d ", v[i]);
  }
}

void mostrarPares(int v[], int n) {
  int i;

  for (i = 0; i < n; i++) {
    if (v[i] % 2 == 0) {
      printf("%d ", v[i]);
    }
  }
}

void mostrarTabla(int t[][3], int filas) {
  int i;
  int j;

  for (i = 0; i < filas; i++) {
    for (j = 0; j < 3; j++) {
      printf("%d ", t[i][j]);
    }
    printf("\n");
  }
}
